// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint256 fund = bound(amount, 1 wei, 1 ether);
        vm.deal(address(this), fund);
        (bool sent, ) = address(c).call{value: fund}("");
        require(sent);

        uint256 before = address(c).balance;

        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool ok;
        try c.withdraw(bound(amount, 0, before)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || address(c).balance == before);
    }
}
